  const l=labels.get(i.id)||{labelVisible:false,labelX:(i.radius+5)*scale,labelY:-4*scale},r=i.radius,types=Object.keys(MAP_COLORS).filter(k=>i[k]?.length),primary=types.includes(layer)?layer:types[0],c=MAP_COLORS[primary]||'#a1b4c0';
  const breakdown=types.map(k=>`${i[k].length} ${k==='companies'?(i[k].length===1?'company':'companies'):k}`).join(' · ');
  const label=i.reference?`${i.city}, capital of ${countryName(i.country)}`:`${i.city||countryName(i.country)}, ${countryName(i.country)}: ${breakdown}${i.approximate?'; city not established':'; approximate locality centre'}${i.kinds?.length?' · '+i.kinds.map(k=>k==='company_hq'?'Company HQ':k==='country_research_index'?'Country association':k.includes('office')||k.includes('contact')?'Office / contact city':k==='published_meeting_location'?'Meeting location':hubKindLabel(k)).join(', '):''}`;
  const hollow=i.approximate||(!i.companies?.length&&i.kinds?.every(k=>!isTestOrResearchLocality(k)&&k!=='published_office_or_contact_city'));
