  return `<g class="geo-point ${i.reference?'capital-reference':'marker locality-marker'}${i.approximate?' country-approximate':''}${picked?' picked':''}" ${i.reference?'':`data-marker="locality" data-id="${esc(i.id)}" role="button" tabindex="0"`} transform="translate(${i.x} ${i.y}) scale(${scale})" aria-label="${esc(label)}" style="--point-color:${c}"><title>${esc(label)}</title>${i.reference?'<circle class="capital-ring" r="3.2"/><circle class="capital-core" r="1"/>':`<circle class="point-hit" r="${Math.max(13,r+4)}"/>${types.map((t,j)=>`<circle class="point-glow" r="${r*2.5+j*4}" fill="url(#glow-${t})"/>`).join('')}<circle class="point-core ${hollow?'hollow':''}" r="${r}"/>${types.length>1?types.filter(t=>t!==primary).map((t,j)=>`<circle class="point-orbit" r="${r+3+j*3}" style="stroke:${MAP_COLORS[t]}"/>`).join(''):''}${i.capital?`<circle class="capital-badge" r="${r+3}"/>`:''}${i.n>=3?`<text class="point-count" y=".5">${i.n}</text>`:''}`}
  <text class="place-label${l.labelVisible?'':' quiet'}${i.reference?' reference-label':''}" x="${l.labelX/scale}" y="${l.labelY/scale}">${esc(i.label)}</text></g>`;
